// PORT-NOTE(raw-ptr-skeleton-no-world-handle): the whole-frame driver —
// walks `g_entities`, dispatches `ent->think`/`ent->s.eType`-keyed subsystem
// calls, updates `level`/`GameCvars`/several g_main.c file-scope globals
// (`gDoSlowMoDuel`, `g_LastFrameTime`, `g_siegeRespawnCheck`, …); no world
// handle.
/// Raven `G_RunFrame`.
///
/// Source: `oracle/oracle/codemp/game/g_main.c:3582-4102`
pub fn G_RunFrame(ctx: GameContext<'_>, levelTime: c_int) {
    unsafe {
        let world = &mut *ctx.world;

        if world.cvars.g_gametype.integer == GT_SIEGE
            && world.cvars.g_siegeRespawn.integer != 0
            && world.globals.g_siegeRespawnCheck < world.level.time
        {
            // check for a respawn wave
            let mut i: c_int = 0;
            while (i as usize) < MAX_CLIENTS {
                let cl_ent = world.g_entities.as_mut_ptr().add(i as usize);
                if (*cl_ent).inuse != QFALSE
                    && !(*cl_ent).client.is_null()
                    && (*(*cl_ent).client).tempSpectate > world.level.time
                    && (*(*cl_ent).client).sess.sessionTeam != TEAM_SPECTATOR
                {
                    respawn(ctx, cl_ent);
                    (*(*cl_ent).client).tempSpectate = 0;
                }
                i += 1;
            }

            world.globals.g_siegeRespawnCheck =
                world.level.time + world.cvars.g_siegeRespawn.integer * 1000;
        }

        if world.globals.gDoSlowMoDuel != QFALSE {
            if world.level.restarted != QFALSE {
                let mut buf: [c_char; 128] = [0; 128];
                trap::Cvar_VariableStringBuffer(
                    ctx.engine,
                    mp_abi::game::syscalls::G_CVAR_VARIABLE_STRING_BUFFER::GCvarVariableStringBufferArgs::new(
                        cstr("timescale"),
                        buf.as_mut_ptr(),
                        buf.len() as c_int,
                    ),
                );
                let t_fval = atof(buf.as_ptr()) as f32;
                trap::Cvar_Set(
                    ctx.engine,
                    mp_abi::game::syscalls::G_CVAR_SET::GCvarSetArgs::new(
                        cstr("timescale"),
                        cstr("1"),
                    ),
                );
                if t_fval == 1.0f32 {
                    world.globals.gDoSlowMoDuel = QFALSE;
                }
            } else {
                // difference in time between when the slow motion was initiated and now
                let time_dif = (world.level.time - world.globals.gSlowMoDuelTime) as f32;

                if time_dif < 150.0 {
                    trap::Cvar_Set(
                        ctx.engine,
                        mp_abi::game::syscalls::G_CVAR_SET::GCvarSetArgs::new(
                            cstr("timescale"),
                            cstr("0.1f"),
                        ),
                    );
                } else if time_dif < 1150.0 {
                    let mut use_dif = time_dif / 1000.0; // scale from 0.1 up to 1
                    if use_dif < 0.1 {
                        use_dif = 0.1;
                    }
                    if use_dif > 1.0 {
                        use_dif = 1.0;
                    }
                    trap::Cvar_Set(
                        ctx.engine,
                        mp_abi::game::syscalls::G_CVAR_SET::GCvarSetArgs::new(
                            cstr("timescale"),
                            cstr(&format!("{}", use_dif)),
                        ),
                    );
                } else {
                    let mut buf: [c_char; 128] = [0; 128];
                    trap::Cvar_VariableStringBuffer(
                        ctx.engine,
                        mp_abi::game::syscalls::G_CVAR_VARIABLE_STRING_BUFFER::GCvarVariableStringBufferArgs::new(
                            cstr("timescale"),
                            buf.as_mut_ptr(),
                            buf.len() as c_int,
                        ),
                    );
                    let t_fval = atof(buf.as_ptr()) as f32;
                    trap::Cvar_Set(
                        ctx.engine,
                        mp_abi::game::syscalls::G_CVAR_SET::GCvarSetArgs::new(
                            cstr("timescale"),
                            cstr("1"),
                        ),
                    );
                    if time_dif > 1500.0 && t_fval == 1.0f32 {
                        world.globals.gDoSlowMoDuel = QFALSE;
                    }
                }
            }
        }

        // if we are waiting for the level to restart, do nothing
        if world.level.restarted != QFALSE {
            return;
        }

        world.level.framenum += 1;
        world.level.previousTime = world.level.time;
        world.level.time = levelTime;
        let _msec = world.level.time - world.level.previousTime;

        if world.cvars.g_allowNPC.integer != 0 {
            NAV_CheckCalcPaths(ctx);
        }

        AI_UpdateGroups(ctx);

        if world.cvars.g_allowNPC.integer != 0 {
            if world.cvars.d_altRoutes.integer != 0 {
                trap::Nav_CheckAllFailedEdges(
                    ctx.engine,
                    mp_abi::game::syscalls::G_NAV_CHECKALLFAILEDEDGES::GNavCheckallfailededgesArgs::new(),
                );
            }
            trap::Nav_ClearCheckedNodes(
                ctx.engine,
                mp_abi::game::syscalls::G_NAV_CLEARCHECKEDNODES::GNavClearcheckednodesArgs::new(),
            );

            // remember last waypoint, clear current one
            let mut i: c_int = 0;
            while i < world.level.num_entities {
                let ent = world.g_entities.as_mut_ptr().add(i as usize);
                if (*ent).inuse == QFALSE {
                    i += 1;
                    continue;
                }

                if (*ent).waypoint != WAYPOINT_NONE && (*ent).noWaypointTime < world.level.time {
                    (*ent).lastWaypoint = (*ent).waypoint;
                    (*ent).waypoint = WAYPOINT_NONE;
                }
                if world.cvars.d_altRoutes.integer != 0 {
                    trap::Nav_CheckFailedNodes(
                        ctx.engine,
                        mp_abi::game::syscalls::G_NAV_CHECKFAILEDNODES::GNavCheckfailednodesArgs::new(ent),
                    );
                }
                i += 1;
            }

            // Look to clear out old events
            ClearPlayerAlertEvents(ctx);
        }

        world.globals.g_TimeSinceLastFrame = world.level.time - world.globals.g_LastFrameTime;

        // get any cvar changes
        G_UpdateCvars(ctx);

        //
        // go through all allocated objects
        //
        let mut i: c_int = 0;
        while i < world.level.num_entities {
            let ent = world.g_entities.as_mut_ptr().add(i as usize);
            if (*ent).inuse == QFALSE {
                i += 1;
                continue;
            }

            // clear events that are too old
            if world.level.time - (*ent).eventTime > EVENT_VALID_MSEC {
                if (*ent).s.event != 0 {
                    (*ent).s.event = 0; // &= EV_EVENT_BITS;
                    if !(*ent).client.is_null() {
                        (*(*ent).client).ps.externalEvent = 0;
                    }
                }
                if (*ent).freeAfterEvent != QFALSE {
                    // tempEntities or dropped items completely go away after their event
                    if (*ent).s.eFlags & EF_SOUNDTRACKER != 0 {
                        // don't trigger the event again..
                        (*ent).s.event = 0;
                        (*ent).s.eventParm = 0;
                        (*ent).s.eType = 0;
                        (*ent).eventTime = 0;
                    } else {
                        G_FreeEntity(ctx, ent);
                        i += 1;
                        continue;
                    }
                } else if (*ent).unlinkAfterEvent != QFALSE {
                    // items that will respawn will hide themselves after their pickup event
                    (*ent).unlinkAfterEvent = QFALSE;
                    trap::UnlinkEntity(
                        ctx.engine,
                        mp_abi::game::syscalls::G_UNLINKENTITY::GUnlinkentityArgs::new(ent),
                    );
                }
            }

            // temporary entities don't think
            if (*ent).freeAfterEvent != QFALSE {
                i += 1;
                continue;
            }

            if (*ent).r.linked == QFALSE && (*ent).neverFree != QFALSE {
                i += 1;
                continue;
            }

            if (*ent).s.eType == entityType_t::ET_MISSILE as c_int {
                G_RunMissile(ctx, ent);
                i += 1;
                continue;
            }

            if (*ent).s.eType == entityType_t::ET_ITEM as c_int || (*ent).physicsObject != QFALSE {
                G_RunItem(ctx, ent);
                i += 1;
                continue;
            }

            if (*ent).s.eType == entityType_t::ET_MOVER as c_int {
                G_RunMover(ctx, ent);
                i += 1;
                continue;
            }

            if (i as usize) < MAX_CLIENTS {
                G_CheckClientTimeouts(ctx, ent);

                let client = (*ent).client;
                if (*client).inSpaceIndex != 0 && (*client).inSpaceIndex != ENTITYNUM_NONE {
                    // we're in space, check for suffocating and for exiting
                    let spacetrigger = world
                        .g_entities
                        .as_mut_ptr()
                        .add((*client).inSpaceIndex as usize);

                    if (*spacetrigger).inuse == QFALSE
                        || G_PointInBounds(
                            (*client).ps.origin,
                            (*spacetrigger).r.absmin,
                            (*spacetrigger).r.absmax,
                        ) == QFALSE
                    {
                        // no longer in space then I suppose
                        (*client).inSpaceIndex = 0;
                    } else {
                        // check for suffocation
                        if (*client).inSpaceSuffocation < world.level.time {
                            // suffocate!
                            if (*ent).health > 0 && (*ent).takedamage != QFALSE {
                                // if they're still alive..
                                let dmg = world.bg_state.rng.Q_irand(50, 70);
                                G_Damage(
                                    ctx,
                                    ent,
                                    spacetrigger,
                                    spacetrigger,
                                    None,
                                    (*client).ps.origin,
                                    dmg,
                                    DAMAGE_NO_ARMOR,
                                    MOD_SUICIDE as c_int,
                                );

                                if (*ent).health > 0 {
                                    // play the choking sound
                                    let n = world.bg_state.rng.Q_irand(1, 3);
                                    let snd =
                                        G_SoundIndex(cstr(&format!("*choke{}.wav", n)).as_ptr());
                                    G_EntitySound(ctx, ent, CHAN_VOICE, snd);

                                    // make them grasp their throat
                                    (*client).ps.forceHandExtend = HANDEXTEND_CHOKE as c_int;
                                    (*client).ps.forceHandExtendTime = world.level.time + 2000;
                                }
                            }

                            (*client).inSpaceSuffocation =
                                world.level.time + world.bg_state.rng.Q_irand(100, 200);
                        }
                    }
                }

                if (*client).isHacking != 0 {
                    // hacking checks
                    let hacked = world
                        .g_entities
                        .as_mut_ptr()
                        .add((*client).isHacking as usize);
                    let mut ang_dif: vec3_t = [0.0; 3];

                    crate::q_math::_VectorSubtract(
                        (*client).ps.viewangles,
                        (*client).hackingAngles,
                        &mut ang_dif,
                    );

                    // keep him in the "use" anim
                    if (*client).ps.torsoAnim != BOTH_CONSOLE1 as c_int {
                        G_SetAnim(
                            ent,
                            std::ptr::null_mut(),
                            SETANIM_TORSO,
                            BOTH_CONSOLE1 as c_int,
                            SETANIM_FLAG_OVERRIDE | SETANIM_FLAG_HOLD,
                            0,
                        );
                    } else {
                        (*client).ps.torsoTimer = 500;
                    }
                    (*client).ps.weaponTime = (*client).ps.torsoTimer;

                    if (*client).pers.cmd.buttons & BUTTON_USE == 0 {
                        // have to keep holding use
                        (*client).isHacking = 0;
                        (*client).ps.hackingTime = 0;
                    } else if hacked.is_null() || (*hacked).inuse == QFALSE {
                        // shouldn't happen, but safety first
                        (*client).isHacking = 0;
                        (*client).ps.hackingTime = 0;
                    } else if G_PointInBounds(
                        (*client).ps.origin,
                        (*hacked).r.absmin,
                        (*hacked).r.absmax,
                    ) == QFALSE
                    {
                        // they stepped outside the thing they're hacking, so reset hacking time
                        (*client).isHacking = 0;
                        (*client).ps.hackingTime = 0;
                    } else if VectorLength(ang_dif) > 10.0f32 {
                        // must remain facing generally the same angle as when we start
                        (*client).isHacking = 0;
                        (*client).ps.hackingTime = 0;
                    }
                }

                // JETPACK_DEFUEL_RATE ~= 200, JETPACK_REFUEL_RATE ~= 150 (g_main.c:3895-3896 local #defines)
                if (*client).jetPackOn != QFALSE {
                    // using jetpack, drain fuel
                    if (*client).jetPackDebReduce < world.level.time {
                        if (*client).pers.cmd.upmove > 0 {
                            // take more if they're thrusting
                            (*client).ps.jetpackFuel -= 2;
                        } else {
                            (*client).ps.jetpackFuel -= 1;
                        }

                        if (*client).ps.jetpackFuel <= 0 {
                            // turn it off
                            (*client).ps.jetpackFuel = 0;
                            Jetpack_Off(ent);
                        }
                        (*client).jetPackDebReduce = world.level.time + 200;
                    }
                } else if (*client).ps.jetpackFuel < 100 {
                    // recharge jetpack
                    if (*client).jetPackDebRecharge < world.level.time {
                        (*client).ps.jetpackFuel += 1;
                        (*client).jetPackDebRecharge = world.level.time + 150;
                    }
                }

                // CLOAK_DEFUEL_RATE ~= 200, CLOAK_REFUEL_RATE ~= 150 (g_main.c:3927-3928 local #defines)
                if (*client).ps.powerups[PW_CLOAKED as usize] != 0 {
                    // using cloak, drain battery
                    if (*client).cloakDebReduce < world.level.time {
                        (*client).ps.cloakFuel -= 1;

                        if (*client).ps.cloakFuel <= 0 {
                            // turn it off
                            (*client).ps.cloakFuel = 0;
                            Jedi_Decloak(ctx, ent);
                        }
                        (*client).cloakDebReduce = world.level.time + 200;
                    }
                } else if (*client).ps.cloakFuel < 100 {
                    // recharge cloak
                    if (*client).cloakDebRecharge < world.level.time {
                        (*client).ps.cloakFuel += 1;
                        (*client).cloakDebRecharge = world.level.time + 150;
                    }
                }

                if world.cvars.g_gametype.integer == GT_SIEGE
                    && (*client).siegeClass != -1
                    && world.bg_state.bgSiegeClasses[(*client).siegeClass as usize].classflags
                        & (1 << (CFL_STATVIEWER as c_int))
                        != 0
                {
                    // see if it's time to send this guy an update of extended info
                    if (*client).siegeEDataSend < world.level.time {
                        G_SiegeClientExData(ctx, ent);
                        (*client).siegeEDataSend = world.level.time + 1000; // once every sec seems ok
                    }
                }

                if world.level.intermissiontime == 0
                    && (*client).ps.pm_flags & PMF_FOLLOW == 0
                    && (*client).sess.sessionTeam != TEAM_SPECTATOR
                {
                    WP_ForcePowersUpdate(ctx, ent, &mut (*client).pers.cmd);
                    WP_SaberPositionUpdate(ctx, ent, &mut (*client).pers.cmd);
                    WP_SaberStartMissileBlockCheck(ctx, ent, &mut (*client).pers.cmd);
                }

                if world.cvars.g_allowNPC.integer != 0 {
                    // This was originally intended to only be done for client 0.
                    // Make sure it doesn't slow things down too much with lots of clients in game.
                    NAV_FindPlayerWaypoint(ctx, i);
                }

                trap::ICARUS_MaintainTaskManager(
                    ctx.engine,
                    mp_abi::game::syscalls::G_ICARUS_MAINTAINTASKMANAGER::GIcarusMaintaintaskmanagerArgs::new((*ent).s.number),
                );

                G_RunClient(ctx, ent);
                i += 1;
                continue;
            } else if (*ent).s.eType == entityType_t::ET_NPC as c_int {
                let client = (*ent).client;
                // turn off any expired powerups
                let mut j: usize = 0;
                while j < MAX_POWERUPS {
                    if (*client).ps.powerups[j] < world.level.time {
                        (*client).ps.powerups[j] = 0;
                    }
                    j += 1;
                }

                WP_ForcePowersUpdate(ctx, ent, &mut (*client).pers.cmd);
                WP_SaberPositionUpdate(ctx, ent, &mut (*client).pers.cmd);
                WP_SaberStartMissileBlockCheck(ctx, ent, &mut (*client).pers.cmd);
            }

            G_RunThink(ctx, ent);

            if world.cvars.g_allowNPC.integer != 0 {
                ClearNPCGlobals(ctx);
            }
            i += 1;
        }

        SiegeCheckTimers(ctx);

        trap::ROFF_UpdateEntities(
            ctx.engine,
            mp_abi::game::syscalls::G_ROFF_UPDATE_ENTITIES::GRoffUpdateEntitiesArgs::new(),
        );

        // perform final fixups on the players
        let mut i: c_int = 0;
        while i < world.level.maxclients {
            let ent = world.g_entities.as_mut_ptr().add(i as usize);
            if (*ent).inuse != QFALSE {
                ClientEndFrame(ctx, ent);
            }
            i += 1;
        }

        // see if it is time to do a tournement restart
        CheckTournament(ctx);

        // see if it is time to end the level
        CheckExitRules(ctx);

        // update to team status?
        CheckTeamStatus(ctx);

        // cancel vote if timed out
        CheckVote(ctx);

        // check team votes
        CheckTeamVote(ctx, TEAM_RED as c_int);
        CheckTeamVote(ctx, TEAM_BLUE as c_int);

        // for tracking changes
        CheckCvars(ctx);

        if world.cvars.g_listEntity.integer != 0 {
            let mut i: c_int = 0;
            while (i as usize) < MAX_GENTITIES {
                let classname = world.g_entities[i as usize].classname;
                let name = if classname.is_null() {
                    String::new()
                } else {
                    cstr_to_str(classname)
                };
                G_Printf(ctx, cstr(&format!("{:4}: {}\n", i, name)).as_ptr());
                i += 1;
            }
            trap::Cvar_Set(
                ctx.engine,
                mp_abi::game::syscalls::G_CVAR_SET::GCvarSetArgs::new(
                    cstr("g_listEntity"),
                    cstr("0"),
                ),
            );
        }

        // At the end of the frame, send out the ghoul2 kill queue, if there is one
        G_SendG2KillQueue(ctx);

        if world.globals.gQueueScoreMessage != QFALSE {
            if world.globals.gQueueScoreMessageTime < world.level.time {
                SendScoreboardMessageToAllClients(ctx);

                world.globals.gQueueScoreMessageTime = 0;
                world.globals.gQueueScoreMessage = QFALSE;
            }
        }

        world.globals.g_LastFrameTime = world.level.time;
    }
}

// PORT-NOTE(raw-ptr-skeleton-no-world-handle): the C body's
// `static char text[1024]` rotating scratch return buffer (va/vtos idiom →
// owned return value) plus its `Com_sprintf` call is itself
// unported (`q_shared.rs::Com_sprintf`, parked `variadic-c-abi`) — this
// function cannot be finished until that seam lands.
/// Raven `G_GetStringEdString`.
///
/// Source: `oracle/oracle/codemp/game/g_main.c:4104-4120`
pub fn G_GetStringEdString(
    ctx: GameContext<'_>,
    refSection: *mut c_char,
    refName: *mut c_char,
) -> *const c_char {
    // Well, it would've been lovely doing it the above way, but it would mean
    // mixing languages for the client depending on what the server is. So
    // we'll mark this as a stringed reference with @@@ and send the refname
    // to the client, and when it goes to print it will get scanned for the
    // stringed reference indication and dealt with properly.
    //
    // PORT-NOTE(static-scratch-buffer): Raven's `static char text[1024]` is a
    // single reused rotating buffer; no GameWorld field is cited for it, so
    // this leaks a fresh `'static` allocation per call (an owned-return
    // divergence, not a rotating-buffer aliasing bug).
    unsafe {
        let name = cstr_to_str(refName);
        let text = format!("@@@{}", name);
        let leaked: &'static CString = Box::leak(Box::new(cstr(&text)));
        leaked.as_ptr()
    }
}
